子查询 嵌套 JOIN，外层 `@combine` 组合跨表条件
![输入图片说明](https://foruda.gitee.com/images/1767367879862512465/0e4e59aa_485581.png "屏幕截图")
```js
{
    "[]": {
        "Comment": {
            "@from@": {
                "join": {
                    "</User": { // LEFT JOIN User
                        "@column": "sex,name"
                    },
                    "</Moment": { // LEFT JOIN Moment
                        "@column": "content:momentContent,date:momentDate" // JOIN 后重名字段需要去掉或重命名
                    }
                },
                "Comment": {}, // 最上方表对象为主表
                "User": {
                    "@column": "id,sex,name",
                    "id@": "/Comment/userId" // ON User.id = Comment.userId
                },
                "Moment": {
                    "@column": "id,userId,content,date",
                    "id@": "/Comment/Comment" // ON Moment.id = Comment.Comment
                }
            }, // 以下为跨表条件及组合，因为已经 JOIN 到了临时表，所以在临时表中是同一张表的字段
            "toId&{}": "!=null;<=0",
            "sex{}": "!=null",
            "sex|{}": [
                0,
                1
            ],
            "momentDate&{}": "!=null,%2=0",
            "@combine": "toId&{} | (sex{} & sex|{}) | momentDate&{}", // 任意与或非组合表达式
            "@explain": true // 返回查询 SQL 及计划
        }
    }
}
```

