SELECT `Comment`.*, `User`.`sex`,`User`.`name`, `Moment`.`content` AS `momentContent`,`Moment`.`date` AS `momentDate` FROM `sys`.`Comment` AS `Comment` LEFT JOIN ( SELECT `id`,`sex`,`name` FROM `sys`.`apijson_user` ) AS `User` ON `User`.`id` = `Comment`.`userId` LEFT JOIN ( SELECT `id`,`userId`,`content`,`date` FROM `sys`.`Moment` ) AS `Moment` ON `Moment`.`id` = `Comment`.`momentId` WHERE ( `Comment`.`toId` IS NOT NULL AND `Comment`.`toId` <=0 ) OR (( (`User`.`sex`) IS NOT NULL ) AND ( (`User`.`sex`) IN (0,1) )) OR ( (`Moment`.`date`) IS NOT NULL AND (`Moment`.`date`) %2=0 ) LIMIT 10
```

